window.QUIZ_TOPICS={"N": ["Fundamentos e modelos", "JSON e PostgreSQL", "Documentos e agregados", "Cassandra e CQL", "Grafos e Cypher"], "M": ["Modelagem e aplicações", "Solução gráfica", "Método Simplex", "Dualidade", "Sensibilidade"], "L": ["Fundamentos e engenharias", "Variabilidade", "Estratégias de adoção", "Aplicação e rastreabilidade", "Testes de LPS"], "A": ["Componentes e interface", "Persistência", "Rede e Offline First", "Arquiteturas e Redux", "Segurança e qualidade"], "B": ["Formatos e HTTP", "Java Web e JDBC", "Spring e persistência", "Mensageria", "Serviços e integração"]};
window.QUIZ_DATA=[{"id": "N1", "subject": "NoSQL", "group": "N", "html": "<p>Qual associação está correta?<\/p>", "type": "choice", "options": ["<p>MongoDB–grafos<\/p>", "<p>Neo4j–grafos<\/p>", "<p>Cassandra–documentos<\/p>", "<p>Redis–relacional exclusivo<\/p>"], "correct": 1, "topic": 0, "explain": "Neo4j é grafos; MongoDB documentos; Cassandra famílias de colunas; Redis chave-valor."}, {"id": "N2", "subject": "NoSQL", "group": "N", "html": "<p>Para obter cliente como texto no PostgreSQL:<\/p>", "type": "choice", "options": ["<p><code>detalhes -&gt; 'cliente'<\/code><\/p>", "<p><code>detalhes -&gt;&gt; 'cliente'<\/code><\/p>", "<p><code>jsonb_pretty(detalhes)<\/code><\/p>", "<p><code>count(cliente)<\/code><\/p>"], "correct": 1, "topic": 1, "explain": "->> retorna texto; -> retorna elemento JSON/JSONB."}, {"id": "N3", "subject": "NoSQL", "group": "N", "html": "<p>Schemaless quer dizer:<\/p>", "type": "choice", "options": ["<p>dados sem significado<\/p>", "<p>nenhum registro pode ter estrutura<\/p>", "<p>não se exige esquema rígido uniforme previamente fixado<\/p>", "<p>validação é proibida<\/p>"], "correct": 2, "topic": 0, "explain": "Flexibilidade não elimina organização/validação."}, {"id": "N4", "subject": "NoSQL", "group": "N", "html": "<p>O que faz <code>db.alunos.find({nota: {$gte: 7}})<\/code>?<\/p>", "type": "choice", "topic": 2, "options": ["Seleciona alunos com nota maior ou igual a 7", "Altera todas as notas para 7", "Remove alunos com nota abaixo de 7", "Retorna somente alunos com nota exatamente 7"], "correct": 0, "explain": "seleciona documentos com nota maior ou igual a 7. Não altera notas."}, {"id": "N5", "subject": "NoSQL", "group": "N", "html": "<p>Em <code>PRIMARY KEY ((loja,mes),dia)<\/code>, quais campos definem a partição e qual é clustering?<\/p>", "type": "choice", "topic": 3, "options": ["loja e mes definem a partição; dia é clustering", "loja é partição; mes e dia são clustering", "dia define a partição; loja e mes são índices", "Todos são clustering; não existe chave de partição"], "correct": 0, "explain": "loja e mes formam a partition key; dia é clustering."}, {"id": "N6", "subject": "NoSQL", "group": "N", "html": "<p>Para representar seguidores e percorrer relacionamentos, qual modelo é o encaixe mais direto?<\/p>", "type": "choice", "topic": 4, "options": ["Grafos", "Chave-valor sem consulta a relações", "Tabelas de cache por expiração", "Arquivos de texto sequenciais"], "correct": 0, "explain": "grafos, com relacionamentos explícitos entre entidades."}, {"id": "N7", "subject": "NoSQL", "group": "N", "html": "<p>O que retorna <code>MATCH (a:Pessoa)-[:SEGUE]-&gt;(b:Pessoa) RETURN b.nome<\/code>? Pode haver repetição?<\/p>", "type": "choice", "topic": 4, "options": ["Nomes das pessoas seguidas; podem se repetir", "Nomes dos seguidores, sempre sem repetição", "Todos os nomes, mesmo sem relação SEGUE", "Quantidade de seguidores agrupada por pessoa"], "correct": 0, "explain": "nomes de pessoas seguidas por pessoas correspondentes ao padrão. Pode repetir: não há DISTINCT e uma pessoa pode ter vários seguidores."}, {"id": "N8", "subject": "NoSQL", "group": "N", "html": "<p>Embutir itens no documento de um pedido significa:<\/p>", "type": "choice", "options": ["<p>criar grafo<\/p>", "<p>reunir agregado<\/p>", "<p>eliminar toda duplicação<\/p>", "<p>impor esquema uniforme a todas as coleções<\/p>"], "correct": 1, "topic": 2, "explain": "Pedido/itens formam agregado; isso não garante ausência de duplicação."}, {"id": "N9", "subject": "NoSQL", "group": "N", "html": "<p>Diferencie replicação e particionamento.<\/p>", "type": "choice", "topic": 0, "options": ["Replicar mantém cópias; particionar divide os dados", "Replicar divide dados; particionar só duplica", "Os dois mecanismos apenas aumentam a memória da máquina", "Particionar elimina a necessidade de comunicação em rede"], "correct": 0, "explain": "replicação mantém cópias; particionamento divide subconjuntos entre nós."}, {"id": "N10", "subject": "NoSQL", "group": "N", "html": "<p>Sobre ALLOW FILTERING no Cassandra, qual afirmação é correta?<\/p>", "type": "choice", "options": ["Autoriza certas filtragens, mas não garante eficiência", "Garante o uso de índice em qualquer consulta", "Cria automaticamente a partition key", "Elimina a necessidade de modelar pelas consultas"], "correct": 0, "topic": 3, "explain": "A filtragem autorizada pode ser custosa."}, {"id": "M1", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>A consome 2 horas por unidade e B consome 3; há no máximo 60 horas. Escreva a restrição para quantidades x e y.<\/p>", "type": "choice", "topic": 0, "options": ["2x + 3y ≤ 60", "2x + 3y ≥ 60", "3x + 2y ≤ 60", "x + y = 60"], "correct": 0, "explain": "2x+3y≤60. Acrescente x,y≥0 no modelo completo."}, {"id": "M2", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>É preciso obter pelo menos 25 unidades entre produção própria x e compra y. Escreva a restrição.<\/p>", "type": "choice", "topic": 0, "options": ["x + y ≥ 25", "x + y ≤ 25", "x − y ≥ 25", "25x + 25y = 1"], "correct": 0, "explain": "x+y≥25; “pelo menos” é limite inferior."}, {"id": "M3", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Resolva por vértices: <code>max 4x+3y<\/code>, com <code>x+y≤5<\/code>, <code>x≤3<\/code>, <code>y≤4<\/code>, <code>x,y≥0<\/code>.<\/p>", "type": "choice", "topic": 1, "options": ["x=3, y=2 e Z=18", "x=1, y=4 e Z=16", "x=3, y=4 e Z=24", "x=0, y=4 e Z=12"], "correct": 0, "explain": "vértices (0,0), (3,0), (3,2), (1,4), (0,4); Z=0,12,18,16,12. Ótimo (3,2), Z=18."}, {"id": "M4", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>No teste de razão do Simplex primal, coeficientes positivos da coluna entrante são 2 e 1; termos independentes, 8 e 3. Qual linha sai?<\/p>", "type": "choice", "topic": 2, "options": ["A segunda: 3/1 é a menor razão admissível", "A primeira: 8/2 é a maior razão", "A primeira: seu coeficiente 2 é maior", "Nenhuma: ambas as razões são positivas"], "correct": 0, "explain": "segunda linha, pois 8/2=4 e 3/1=3; menor razão admissível."}, {"id": "M5", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Escreva o dual: <code>max 5x+4y<\/code>, com <code>2x+y≤10<\/code>, <code>x+3y≤12<\/code>, <code>x,y≥0<\/code>.<\/p>", "type": "choice", "topic": 3, "options": ["min 10u+12v; 2u+v≥5; u+3v≥4; u,v≥0", "max 10u+12v; 2u+v≤5; u+3v≤4; u,v≥0", "min 5u+4v; 2u+v≥10; u+3v≥12; u,v≥0", "min 10u+12v; 2u+3v≥5; u+v≥4; u,v≥0"], "correct": 0, "explain": "min 10u+12v, com 2u+v≥5, u+3v≥4, u,v≥0. Matriz transposta e papéis de b/c trocados."}, {"id": "M6", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Preço-sombra 6; capacidade aumenta 2 unidades dentro do intervalo de validade. Quanto varia o ótimo?<\/p>", "type": "choice", "topic": 4, "options": ["Aumenta 12 unidades", "Aumenta 3 unidades", "Aumenta 6 unidades", "Diminui 12 unidades"], "correct": 0, "explain": "aumento de 12 unidades no objetivo, nas condições dadas."}, {"id": "M7", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Uma restrição tem folga zero na solução ótima. Sobre seu preço-sombra:<\/p>", "type": "choice", "options": ["Pode ser zero ou não, conforme o problema", "É obrigatoriamente positivo", "É obrigatoriamente negativo", "É sempre igual à folga"], "correct": 0, "topic": 3, "explain": "Folga zero permite preço zero. Folga estritamente positiva exige preço zero."}, {"id": "M8", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Estoque inicial 10, produção 40, demanda 35. Estoque final?<\/p>", "type": "choice", "topic": 0, "options": ["15 unidades", "65 unidades", "5 unidades", "25 unidades"], "correct": 0, "explain": "10+40−35=15 unidades."}, {"id": "M9", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Mistura com pelo menos 30% de nutriente; x contém 20% e y contém 50%. Escreva a restrição.<\/p>", "type": "choice", "topic": 0, "options": ["0,20x+0,50y ≥ 0,30(x+y)", "0,20x+0,50y ≤ 0,30(x+y)", "0,20x+0,50y ≥ 0,30", "x+y ≥ 0,30"], "correct": 0, "explain": "0,20x+0,50y≥0,30(x+y); equivale a y≥0,5x, com não negatividade."}, {"id": "M10", "subject": "Métodos Quantitativos", "group": "M", "html": "<p>Para <code>max 3x+2y<\/code>, <code>x+y≤4<\/code>, <code>x≤2<\/code>, <code>y≤3<\/code>, o ótimo é (2,2), Z=10 e o preço-sombra da primeira restrição é 2. Se a capacidade passa a 6, é correto prever ganho de 4? Calcule o novo ótimo.<\/p>", "type": "choice", "topic": 4, "options": ["Não: o novo ótimo é (2,3), Z=12; o preço marginal mudou", "Sim: o novo ótimo vale 14 em qualquer capacidade", "Não: o novo ótimo é (0,3), Z=6", "Sim: o novo ótimo é (3,2), Z=13"], "correct": 0, "explain": "não. O preço 2 só se mantém até capacidade 5, fixados os outros limites. Com capacidade 6, ótimo (2,3), Z=12; ganho de 2, não 4."}, {"id": "L1", "subject": "LPS", "group": "L", "html": "<p>Qual engenharia cria os ativos reutilizáveis?<\/p>", "type": "choice", "topic": 0, "options": ["Engenharia do domínio", "Engenharia da aplicação", "Somente a equipe de suporte de cada cliente", "Somente a gestão de contratos"], "correct": 0, "explain": "engenharia do domínio: desenvolve para reuso e para a família."}, {"id": "L2", "subject": "LPS", "group": "L", "html": "<p>Qual engenharia seleciona as variantes de um produto para uma clínica específica?<\/p>", "type": "choice", "topic": 0, "options": ["Engenharia da aplicação", "Engenharia do domínio, sem requisitos do cliente", "Somente a auditoria externa", "A ferramenta de teste, sem configuração"], "correct": 0, "explain": "engenharia da aplicação: deriva produto concreto."}, {"id": "L3", "subject": "LPS", "group": "L", "html": "<p>No ponto de variação “autenticação”, senha e biometria são o quê?<\/p>", "type": "choice", "topic": 1, "options": ["Variantes", "Domínios de negócio independentes", "Requisitos delta necessariamente", "Arquiteturas de referência completas"], "correct": 0, "explain": "variantes do ponto de variação."}, {"id": "L4", "subject": "LPS", "group": "L", "html": "<p>A requires B: A presente/B ausente é configuração válida?<\/p>", "type": "choice", "topic": 1, "options": ["Não, pois selecionar A exige selecionar B", "Sim, porque requires apenas sugere B", "Sim, porque A e B se excluem", "Não, porque A é sempre proibida"], "correct": 0, "explain": "não; selecionar A exige B."}, {"id": "L5", "subject": "LPS", "group": "L", "html": "<p>Extrair comunalidades de produtos existentes é adoção:<\/p>", "type": "choice", "options": ["<p>proativa<\/p>", "<p>extrativa<\/p>", "<p>força bruta<\/p>", "<p>aplicação pura<\/p>"], "correct": 1, "topic": 2, "explain": "Extrativa parte de sistemas existentes."}, {"id": "L6", "subject": "LPS", "group": "L", "html": "<p>Para que serve o Modelo Ortogonal de Variabilidade?<\/p>", "type": "choice", "topic": 1, "options": ["Documentar variabilidade e conectá-la aos artefatos", "Substituir os requisitos por código-fonte", "Eliminar todas as diferenças entre produtos", "Testar automaticamente todas as configurações"], "correct": 0, "explain": "documentar pontos, variantes, dependências/restrições e sua conexão com artefatos de desenvolvimento."}, {"id": "L7", "subject": "LPS", "group": "L", "html": "<p>O que é requisito delta?<\/p>", "type": "choice", "topic": 3, "options": ["Necessidade da aplicação não totalmente coberta pelo domínio", "Qualquer requisito comum a todos os produtos", "Um defeito necessariamente causado pelo cliente", "Uma variante obrigatória já implementada"], "correct": 0, "explain": "necessidade da aplicação não completamente coberta pelos requisitos/ativos de domínio; exige avaliação de impacto."}, {"id": "L8", "subject": "LPS", "group": "L", "html": "<p>Depois de testar os ativos de domínio, o que fazer na aplicação?<\/p>", "type": "choice", "options": ["Testar configuração, integração e requisitos específicos", "Dispensar qualquer teste adicional", "Testar apenas a cor da interface", "Remover os testes reutilizáveis"], "correct": 0, "topic": 4, "explain": "Configuração, integração e deltas precisam de testes de aplicação."}, {"id": "L9", "subject": "LPS", "group": "L", "html": "<p>Quatro pontos independentes, exatamente uma escolha entre duas variantes em cada: quantas configurações sem outras restrições?<\/p>", "type": "choice", "topic": 1, "options": ["16", "8", "4", "32"], "correct": 0, "explain": "2^4=16 nas condições dadas."}, {"id": "L10", "subject": "LPS", "group": "L", "html": "<p>Mudança em variante altera requisito/código, mas o teste ficou desatualizado. Qual prática ajuda a identificar esse impacto?<\/p>", "type": "choice", "topic": 3, "options": ["Rastreabilidade", "Apenas contagem de linhas de código", "Somente renomear a variante", "Desativar os testes comuns"], "correct": 0, "explain": "rastreabilidade entre variabilidade, requisitos, implementação e testes."}, {"id": "A1", "subject": "Android", "group": "A", "html": "<p>Diferencie props e state.<\/p>", "type": "choice", "topic": 0, "options": ["Props são recebidas; state é gerenciado pelo componente", "Props são banco local; state é banco remoto", "Props são sempre mutáveis pelo filho; state nunca muda", "State vem apenas da URL; props são funções de teste"], "correct": 0, "explain": "props recebidas do pai; state gerenciado pelo componente para representar dados mutáveis."}, {"id": "A2", "subject": "Android", "group": "A", "html": "<p>Para lista grande: FlatList ou ScrollView com todos os filhos? Por quê?<\/p>", "type": "choice", "topic": 0, "options": ["FlatList, por virtualizar a renderização dos itens", "ScrollView, pois sempre renderiza menos itens", "ScrollView, pois não usa memória para os filhos", "FlatList, porque transforma itens em tabelas SQL"], "correct": 0, "explain": "FlatList, por virtualização; ScrollView com todos os filhos os renderiza juntos."}, {"id": "A3", "subject": "Android", "group": "A", "html": "<p>Por que usar JSON.stringify antes de guardar um objeto em AsyncStorage?<\/p>", "type": "choice", "topic": 1, "options": ["Serializar o objeto em texto antes de armazenar", "Criptografar o objeto com chave secreta", "Criar uma tabela relacional automaticamente", "Transformar uma Promise em operação síncrona"], "correct": 0, "explain": "AsyncStorage guarda valores textuais; stringify serializa e parse reconstrói na leitura."}, {"id": "A4", "subject": "Android", "group": "A", "html": "<p>Qual tecnologia fornece um banco relacional local no aplicativo?<\/p>", "type": "choice", "topic": 1, "options": ["SQLite", "MongoDB remoto", "Base64", "Redux"], "correct": 0, "explain": "SQLite é um banco relacional local; Redux gerencia estado, Base64 é codificação e MongoDB remoto requer acesso ao serviço."}, {"id": "A5", "subject": "Android", "group": "A", "html": "<p>Após <code>const r = await fetch(url)<\/code>, como obter o corpo interpretado como JSON?<\/p>", "type": "choice", "topic": 2, "options": ["await r.json()", "JSON.stringify(r)", "r.data()", "await r.executeSql()"], "correct": 0, "explain": "await r.json(); confira também r.ok e trate falhas."}, {"id": "A6", "subject": "Android", "group": "A", "html": "<p>Detectar conectividade em um app Offline First:<\/p>", "type": "choice", "options": ["É só parte da solução; faltam sincronização e conflitos", "Resolve automaticamente conflitos entre edições", "Impede a reentrega de operações pendentes", "Dispensa armazenamento local"], "correct": 0, "topic": 2, "explain": "É preciso sincronizar e lidar com duplicações/conflitos."}, {"id": "A7", "subject": "Android", "group": "A", "html": "<p>No Redux, quem calcula o próximo estado a partir de estado anterior e action?<\/p>", "type": "choice", "topic": 3, "options": ["Reducer", "Dispatcher obrigatório separado do Redux", "Componente TextInput", "Driver SQLite"], "correct": 0, "explain": "reducer, calculando novo estado sem modificar diretamente o anterior."}, {"id": "A8", "subject": "Android", "group": "A", "html": "<p>Base64 garante sigilo? Justifique.<\/p>", "type": "choice", "topic": 4, "options": ["Não: é codificação reversível sem segredo", "Sim: exige uma chave secreta para decodificar", "Sim: é uma função hash de sentido único", "Sim: substitui HTTPS no transporte"], "correct": 0, "explain": "não; é codificação reversível sem chave secreta."}, {"id": "A9", "subject": "Android", "group": "A", "html": "<p>Diferencie <code>onPress={salvar}<\/code> e <code>onPress={salvar()}<\/code>.<\/p>", "type": "choice", "topic": 0, "options": ["A primeira passa a função; a segunda a executa e passa o retorno", "Ambas sempre aguardam o toque para executar salvar", "A primeira executa agora; a segunda passa callback", "Nenhuma das duas aceita função JavaScript"], "correct": 0, "explain": "a primeira passa callback; a segunda executa a função naquele momento e passa seu retorno."}, {"id": "A10", "subject": "Android", "group": "A", "html": "<p>Cite os três modelos de navegação e a função de um deles.<\/p>", "type": "choice", "topic": 0, "options": ["Stack, tabs e drawer; stack organiza avanço e retorno em pilha", "Stack, SQL e drawer; SQL organiza as telas", "Props, state e tabs; state é um menu lateral", "MVC, Flux e Redux; todos são menus nativos"], "correct": 0, "explain": "stack, tabs, drawer; exemplo: stack organiza avanço/retorno em pilha."}, {"id": "B1", "subject": "Back-end", "group": "B", "html": "<p>Qual formato representa dados com tags e hierarquia?<\/p>", "type": "choice", "topic": 0, "options": ["XML", "JDBC", "JMS", "Servlet"], "correct": 0, "explain": "XML; os outros são tecnologias de acesso/mensageria/processamento."}, {"id": "B2", "subject": "Back-end", "group": "B", "html": "<p>Diferencie Servlet e JSP.<\/p>", "type": "choice", "topic": 1, "options": ["Servlet processa requisições; JSP é apresentação traduzida para Servlet", "JSP roda somente no navegador; Servlet só no banco", "Servlet é arquivo de estilo; JSP é driver SQL", "JSP substitui HTTP; Servlet substitui Java"], "correct": 0, "explain": "Servlet processa requisições em Java; JSP é apresentação processada no servidor e traduzida para Servlet."}, {"id": "B3", "subject": "Back-end", "group": "B", "html": "<p>Qual método JDBC é apropriado para executar SELECT e receber um ResultSet?<\/p>", "type": "choice", "topic": 1, "options": ["executeQuery", "executeUpdate", "setInt", "close"], "correct": 0, "explain": "executeQuery; executeUpdate serve para operações como INSERT/UPDATE/DELETE, entre outros comandos adequados."}, {"id": "B4", "subject": "Back-end", "group": "B", "html": "<p>Relacione JPA, Hibernate e Spring Data JPA.<\/p>", "type": "choice", "topic": 2, "options": ["JPA especifica; Hibernate implementa; Spring Data JPA oferece repositórios", "Hibernate especifica; JPA é banco; Spring Data é driver", "Os três são nomes do mesmo servidor HTTP", "JPA é linguagem SQL; Hibernate é broker; Spring Data é XML"], "correct": 0, "explain": "JPA especifica; Hibernate implementa; Spring Data JPA abstrai repositórios usando JPA."}, {"id": "B5", "subject": "Back-end", "group": "B", "html": "<p>Qual anotação do Spring converte o corpo da requisição em um objeto?<\/p>", "type": "choice", "topic": 2, "options": ["@RequestBody", "@PathVariable", "@Entity", "@Id"], "correct": 0, "explain": "@RequestBody. @PathVariable captura parte da URL; @Entity marca entidade JPA."}, {"id": "B6", "subject": "Back-end", "group": "B", "html": "<p>Qual relação entre JMS e RabbitMQ está correta?<\/p>", "type": "choice", "options": ["JMS é API/especificação; RabbitMQ é broker", "São dois nomes de um mesmo produto", "JMS é banco; RabbitMQ é formato de dados", "JMS é protocolo HTTP; RabbitMQ é Servlet"], "correct": 0, "topic": 3, "explain": "JMS é API/especificação; RabbitMQ é broker."}, {"id": "B7", "subject": "Back-end", "group": "B", "html": "<p>Para enviar logs a três filas independentes, qual exchange simples atende: fanout ou direct com uma única chave ligada a uma só fila?<\/p>", "type": "choice", "topic": 3, "options": ["Fanout com as três filas vinculadas", "Direct ligado somente a uma fila", "Uma fila única sem assinantes", "Headers sem nenhum binding"], "correct": 0, "explain": "fanout, com três filas vinculadas; cada uma recebe a publicação."}, {"id": "B8", "subject": "Back-end", "group": "B", "html": "<p>Qual é protocolo e qual é estilo arquitetural: SOAP e REST?<\/p>", "type": "choice", "topic": 4, "options": ["SOAP é protocolo; REST é estilo arquitetural", "REST é protocolo XML; SOAP é banco", "Ambos são bancos de dados distribuídos", "SOAP exige JSON; REST exige WSDL"], "correct": 0, "explain": "SOAP protocolo; REST estilo arquitetural."}, {"id": "B9", "subject": "Back-end", "group": "B", "html": "<p>No GraphQL, que operação altera dados e que função fornece valor de campo?<\/p>", "type": "choice", "topic": 4, "options": ["Mutation altera; resolver obtém valor de campo", "Query altera; schema é sempre o broker", "Resolver é o banco; mutation apenas lê", "Mutation é método DELETE obrigatório; query é GET obrigatório"], "correct": 0, "explain": "mutation altera; resolver fornece valor do campo."}, {"id": "B10", "subject": "Back-end", "group": "B", "html": "<p>Uma API REST stateless pode autenticar com token?<\/p>", "type": "choice", "options": ["Sim, com o contexto necessário em cada requisição", "Não, autenticação exige sempre sessão implícita", "Não, stateless proíbe cabeçalhos", "Sim, mas só se não acessar banco de dados"], "correct": 0, "topic": 4, "explain": "Token pode acompanhar cada requisição, fornecendo contexto suficiente."}, {"id": "N11", "group": "N", "subject": "NoSQL", "topic": 0, "html": "<p>Um aplicativo precisa ampliar a capacidade distribuindo dados entre máquinas. Que tipo de escala está buscando?<\/p>", "options": ["Horizontal", "Vertical", "Normalização até a terceira forma normal", "Conversão obrigatória para XML"], "correct": 0, "explain": "Escala horizontal adiciona nós; vertical aumenta recursos de uma máquina.", "type": "choice"}, {"id": "N12", "group": "N", "subject": "NoSQL", "topic": 0, "html": "<p>Um cadastro aceita documentos com campos diferentes, mas valida cada entrada. Isso é compatível com NoSQL?<\/p>", "options": ["Sim, flexibilidade de esquema não elimina validação", "Não, schemaless proíbe validação", "Não, todos os documentos precisam ter campos idênticos", "Somente se os dados forem imagens"], "correct": 0, "explain": "Schemaless não significa ausência de estrutura ou de regras na aplicação.", "type": "choice"}, {"id": "N13", "group": "N", "subject": "NoSQL", "topic": 0, "html": "<p>Qual afirmação evita uma generalização incorreta sobre NoSQL?<\/p>", "options": ["A escolha do modelo depende das necessidades da aplicação", "Todo NoSQL dispensa consistência", "Todo NoSQL é mais rápido em qualquer consulta", "NoSQL proíbe qualquer linguagem parecida com SQL"], "correct": 0, "explain": "Os modelos atendem necessidades diferentes; não há superioridade universal.", "type": "choice"}, {"id": "N14", "group": "N", "subject": "NoSQL", "topic": 0, "html": "<p>Uma rede mantém cópias dos mesmos dados em servidores diferentes. Qual mecanismo descreve isso?<\/p>", "options": ["Replicação", "Particionamento exclusivo", "Clustering de linhas", "Projeção de campos"], "correct": 0, "explain": "Replicação mantém cópias; particionamento divide o conjunto de dados.", "type": "choice"}, {"id": "N15", "group": "N", "subject": "NoSQL", "topic": 1, "html": "<p>Qual opção descreve JSONB no PostgreSQL?<\/p>", "options": ["Representação binária processada com operações e indexação próprias", "Texto que sempre conserva espaços e chaves duplicadas", "Extensão exclusiva para relações entre nós", "Formato que só admite strings sem arrays"], "correct": 0, "explain": "JSONB processa a representação, diferentemente da preservação textual de JSON.", "type": "choice"}, {"id": "N16", "group": "N", "subject": "NoSQL", "topic": 1, "html": "<p>Qual função apresenta um documento JSONB de maneira legível?<\/p>", "options": ["jsonb_pretty", "json_each", "count", "json_typeof"], "correct": 0, "explain": "jsonb_pretty formata a apresentação; json_each desdobra objetos e count agrega.", "type": "choice"}, {"id": "N17", "group": "N", "subject": "NoSQL", "topic": 1, "html": "<p>Para filtrar nome como texto em dados JSONB, qual expressão está adequada?<\/p>", "options": ["dados -&gt;&gt; &#x27;nome&#x27; = &#x27;Ana&#x27;", "jsonb_pretty(dados) = &#x27;Ana&#x27;", "count(dados) = &#x27;Ana&#x27;", "dados -&gt;&gt; &#x27;nome&#x27; = 10"], "correct": 0, "explain": "O operador ->> extrai texto, que pode ser comparado à string Ana.", "type": "choice"}, {"id": "N18", "group": "N", "subject": "NoSQL", "topic": 1, "html": "<p>Qual afirmação sobre HSTORE está correta?<\/p>", "options": ["Representa pares chave-valor textuais no PostgreSQL", "É linguagem de grafos do Neo4j", "É chave de partição obrigatória do Cassandra", "É coleção BSON do MongoDB"], "correct": 0, "explain": "HSTORE é uma extensão de chave-valor; não confunda com BSON ou Cypher.", "type": "choice"}, {"id": "N19", "group": "N", "subject": "NoSQL", "topic": 2, "html": "<p>No MongoDB, qual comando altera apenas o campo nota de um aluno correspondente?<\/p>", "options": ["updateOne com $set", "find com $gte", "createCollection com capped", "deleteOne com projeção"], "correct": 0, "explain": "updateOne seleciona o documento e $set atualiza os campos indicados.", "type": "choice"}, {"id": "N20", "group": "N", "subject": "NoSQL", "topic": 2, "html": "<p>Qual é a equivalência útil entre relacional e MongoDB?<\/p>", "options": ["Linha corresponde a documento; tabela a coleção", "Linha corresponde a coleção; tabela a documento", "Coluna corresponde a banco; linha a índice", "Tabela corresponde a relacionamento Cypher"], "correct": 0, "explain": "Coleções agrupam documentos; documentos contêm campos.", "type": "choice"}, {"id": "N21", "group": "N", "subject": "NoSQL", "topic": 2, "html": "<p>Um pedido é normalmente lido com todos os seus itens. Embutir itens no documento pode favorecer:<\/p>", "options": ["A recuperação conjunta do agregado", "A ausência absoluta de duplicação em toda a base", "Joins relacionais obrigatórios", "A divisão de cada atributo em um servidor"], "correct": 0, "explain": "Um agregado reúne dados relacionados; a escolha depende do padrão de acesso.", "type": "choice"}, {"id": "N22", "group": "N", "subject": "NoSQL", "topic": 2, "html": "<p>Qual diferença entre deleteOne e drop numa coleção MongoDB?<\/p>", "options": ["deleteOne remove documento correspondente; drop remove coleção", "Ambos removem sempre o banco inteiro", "drop apenas atualiza um campo", "deleteOne cria índice; drop consulta documentos"], "correct": 0, "explain": "O escopo da operação importa: documento e coleção são níveis distintos.", "type": "choice"}, {"id": "N23", "group": "N", "subject": "NoSQL", "topic": 3, "html": "<p>Na chave PRIMARY KEY (sensor, instante), sem parênteses internos, sensor e instante são:<\/p>", "options": ["Chave de partição e coluna de clustering, respectivamente", "Duas chaves de partição independentes", "Duas foreign keys obrigatórias", "Coluna de clustering e chave de partição, respectivamente"], "correct": 0, "explain": "O primeiro elemento simples define a partição; os seguintes são clustering.", "type": "choice"}, {"id": "N24", "group": "N", "subject": "NoSQL", "topic": 3, "html": "<p>Ao modelar tabelas no Cassandra, qual ponto de partida é mais adequado?<\/p>", "options": ["As consultas e padrões de acesso necessários", "Eliminar toda duplicação a qualquer custo", "Garantir joins arbitrários entre todas as tabelas", "Usar ALLOW FILTERING em toda consulta"], "correct": 0, "explain": "A modelagem por consulta favorece acesso eficiente e pode aceitar duplicação.", "type": "choice"}, {"id": "N25", "group": "N", "subject": "NoSQL", "topic": 3, "html": "<p>Qual coleção representa valores únicos no Cassandra?<\/p>", "options": ["set", "list", "map com chaves repetidas", "Uma coluna timestamp"], "correct": 0, "explain": "Set representa unicidade; list é sequência e pode repetir valores.", "type": "choice"}, {"id": "N26", "group": "N", "subject": "NoSQL", "topic": 3, "html": "<p>Qual é a função de um keyspace?<\/p>", "options": ["Agrupar tabelas e configurações como replicação", "Ordenar caracteres dentro de toda string", "Substituir cada documento BSON", "Criar automaticamente relações entre todos os nós"], "correct": 0, "explain": "Keyspace é o agrupamento lógico, com configurações como estratégia de replicação.", "type": "choice"}, {"id": "N27", "group": "N", "subject": "NoSQL", "topic": 4, "html": "<p>Em Cypher, qual comando modifica propriedades de um nó localizado?<\/p>", "options": ["SET", "RETURN", "COUNT", "MATCH sem outra cláusula"], "correct": 0, "explain": "MATCH localiza o padrão; SET altera propriedades.", "type": "choice"}, {"id": "N28", "group": "N", "subject": "NoSQL", "topic": 4, "html": "<p>Em (a)-[r:SEGUE]-&gt;(b), r representa:<\/p>", "options": ["Um relacionamento do tipo SEGUE", "Uma tabela relacional chamada SEGUE", "O rótulo obrigatório de todos os nós", "Um campo JSON de a chamado b"], "correct": 0, "explain": "Colchetes indicam o relacionamento; parênteses indicam nós.", "type": "choice"}, {"id": "N29", "group": "N", "subject": "NoSQL", "topic": 4, "html": "<p>Para excluir um nó junto com seus relacionamentos, reconheça:<\/p>", "options": ["DETACH DELETE", "RETURN DISTINCT", "SET NULL sobre o banco inteiro", "MATCH sem DELETE"], "correct": 0, "explain": "DETACH DELETE remove o nó e os relacionamentos conectados a ele.", "type": "choice"}, {"id": "N30", "group": "N", "subject": "NoSQL", "topic": 4, "html": "<p>Um relacionamento Neo4j pode ter data de início como propriedade?<\/p>", "options": ["Sim, relacionamentos também podem ter propriedades", "Não, só bancos relacionais aceitam datas", "Não, propriedades existem apenas em rótulos", "Sim, mas isso o transforma em coleção MongoDB"], "correct": 0, "explain": "Nós e relacionamentos podem armazenar propriedades, como desde e peso.", "type": "choice"}, {"id": "M11", "group": "M", "subject": "Métodos Quantitativos", "topic": 0, "html": "<p>Cada produto A usa 4 kg e B usa 2 kg; há 80 kg disponíveis. Qual restrição modela a capacidade?<\/p>", "options": ["4x+2y≤80", "4x+2y≥80", "2x+4y=80", "x+y≤4"], "correct": 0, "explain": "Multiplique consumo unitário por quantidade e limite pela disponibilidade.", "type": "choice"}, {"id": "M12", "group": "M", "subject": "Métodos Quantitativos", "topic": 0, "html": "<p>Em um modelo, x é a quantidade de mesas por semana. Qual função maximiza lucro de 30 por mesa e 12 por cadeira y?<\/p>", "options": ["max 30x+12y", "min 30x+12y", "max 12x+30y", "max x+y≤42"], "correct": 0, "explain": "Os coeficientes do objetivo são lucros unitários, coerentes com as variáveis.", "type": "choice"}, {"id": "M13", "group": "M", "subject": "Métodos Quantitativos", "topic": 0, "html": "<p>Num nó de transbordo sem geração nem consumo, vale:<\/p>", "options": ["Entrada total igual à saída total", "Entrada sempre menor que saída", "Saída sempre nula", "Entrada mais saída igual a um"], "correct": 0, "explain": "A conservação do fluxo impõe o balanço no nó intermediário.", "type": "choice"}, {"id": "M14", "group": "M", "subject": "Métodos Quantitativos", "topic": 0, "html": "<p>Uma tarefa deve ser atribuída a exatamente um agente. Como modelar a decisão xij?<\/p>", "options": ["Variável binária e soma dos agentes para a tarefa igual a 1", "Variável livre e soma igual a 0", "Variável sempre igual a 2", "Variável contínua negativa sem restrições"], "correct": 0, "explain": "Alocação um a um usa decisões binárias e restrições de atribuição.", "type": "choice"}, {"id": "M15", "group": "M", "subject": "Métodos Quantitativos", "topic": 1, "html": "<p>Maximize 2x+y, com x+y≤4, x≤3, x,y≥0. Qual é o ótimo?<\/p>", "options": ["(3,1), Z=7", "(0,4), Z=4", "(3,4), Z=10", "(4,0), Z=8"], "correct": 0, "explain": "Os dois últimos pontos violam restrições. Entre os vértices viáveis, (3,1) maximiza Z.", "type": "choice"}, {"id": "M16", "group": "M", "subject": "Métodos Quantitativos", "topic": 1, "html": "<p>Qual ponto é inviável para x+y≤6, x≤4, y≤5 e x,y≥0?<\/p>", "options": ["(4,3)", "(4,2)", "(1,5)", "(0,0)"], "correct": 0, "explain": "Em (4,3), x+y=7 ultrapassa a capacidade 6.", "type": "choice"}, {"id": "M17", "group": "M", "subject": "Métodos Quantitativos", "topic": 1, "html": "<p>Uma região viável é ilimitada. Isso basta para afirmar que o objetivo também é ilimitado?<\/p>", "options": ["Não; depende da função objetivo e do sentido de otimização", "Sim, em qualquer problema", "Sim, desde que exista uma variável x", "Não; toda região ilimitada é inviável"], "correct": 0, "explain": "Região ilimitada pode ter ótimo finito. Geometria da região e direção do objetivo diferem.", "type": "choice"}, {"id": "M18", "group": "M", "subject": "Métodos Quantitativos", "topic": 1, "html": "<p>Dois vértices adjacentes são ótimos e todo o segmento entre eles é viável. Numa PL, o segmento:<\/p>", "options": ["Também contém soluções ótimas", "É sempre inviável", "Contém apenas soluções inteiras", "Elimina a possibilidade de ótimo finito"], "correct": 0, "explain": "A linearidade conserva o valor ótimo ao longo desse segmento.", "type": "choice"}, {"id": "M19", "group": "M", "subject": "Métodos Quantitativos", "topic": 2, "html": "<p>Para transformar 2x+y≤10 em igualdade, usa-se:<\/p>", "options": ["2x+y+s=10, s≥0", "2x+y−s=10, s≥0", "2x+y=10 sem variável adicional", "2x+y+s=0, s≥0"], "correct": 0, "explain": "Folga soma o recurso não utilizado para completar o lado direito.", "type": "choice"}, {"id": "M20", "group": "M", "subject": "Métodos Quantitativos", "topic": 2, "html": "<p>Na coluna entrante do Simplex, coeficiente zero participa do teste de razão como divisor?<\/p>", "options": ["Não; usam-se coeficientes estritamente positivos no teste primal usual", "Sim; basta dividir o termo independente por zero", "Sim; ele sempre determina a saída", "Somente se o termo independente também for zero"], "correct": 0, "explain": "O teste considera coeficientes positivos; divisão por zero não é admissível.", "type": "choice"}, {"id": "M21", "group": "M", "subject": "Métodos Quantitativos", "topic": 2, "html": "<p>Após escolher um pivô de valor 2, qual é a primeira operação de normalização?<\/p>", "options": ["Dividir toda a linha do pivô por 2", "Multiplicar só o termo independente por 2", "Somar 2 a todas as linhas", "Excluir a variável entrante do modelo"], "correct": 0, "explain": "Normalizar torna o pivô igual a 1; depois a coluna é eliminada nas outras linhas.", "type": "choice"}, {"id": "M22", "group": "M", "subject": "Métodos Quantitativos", "topic": 2, "html": "<p>Na convenção Z−4x−y=0 para maximização, há coeficientes negativos na linha Z. Isso indica:<\/p>", "options": ["Possibilidade de melhoria antes de confirmar otimalidade", "Otimalidade garantida", "Inviabilidade automática do modelo", "Necessidade de apagar as restrições"], "correct": 0, "explain": "O critério depende da convenção; nesta, negativos indicam oportunidade de entrada.", "type": "choice"}, {"id": "M23", "group": "M", "subject": "Métodos Quantitativos", "topic": 3, "html": "<p>Um primal padrão tem 3 restrições e 2 variáveis. O dual terá:<\/p>", "options": ["3 variáveis e 2 restrições", "2 variáveis e 3 restrições", "6 variáveis e nenhuma restrição", "Sempre a mesma matriz sem transposição"], "correct": 0, "explain": "Cada restrição primal gera variável dual e cada variável primal gera restrição dual.", "type": "choice"}, {"id": "M24", "group": "M", "subject": "Métodos Quantitativos", "topic": 3, "html": "<p>Para primal max cᵀx com Ax≤b e x≥0, o dual padrão é:<\/p>", "options": ["min bᵀu com Aᵀu≥c e u≥0", "max bᵀu com Au≤c e u≥0", "min cᵀu com Aᵀu≤b e u≤0", "max cᵀx sem restrições"], "correct": 0, "explain": "Transponha A e troque os papéis de b e c, com os sentidos do caso padrão.", "type": "choice"}, {"id": "M25", "group": "M", "subject": "Métodos Quantitativos", "topic": 3, "html": "<p>No ótimo, uma restrição apresenta folga estritamente positiva. Pela complementaridade, a variável dual correspondente é:<\/p>", "options": ["Zero", "Sempre 1", "Obrigatoriamente negativa", "Igual à folga positiva"], "correct": 0, "explain": "O produto da folga pela variável dual é zero; folga positiva força variável dual nula.", "type": "choice"}, {"id": "M26", "group": "M", "subject": "Métodos Quantitativos", "topic": 3, "html": "<p>Soluções viáveis primal max e dual min têm o mesmo valor 42. O que se conclui?<\/p>", "options": ["Ambas são ótimas", "Ambas são inviáveis", "O primal precisa alcançar 84", "É necessário inverter a matriz novamente"], "correct": 0, "explain": "A igualdade dos valores viáveis atinge o limite dado pela dualidade fraca e certifica otimalidade.", "type": "choice"}, {"id": "M27", "group": "M", "subject": "Métodos Quantitativos", "topic": 4, "html": "<p>Preço-sombra 4; recurso aumenta 3 unidades dentro do intervalo válido. A variação prevista de Z é:<\/p>", "options": ["12", "7", "4/3", "3/4"], "correct": 0, "explain": "Use variação marginal vezes alteração do recurso: 4×3=12.", "type": "choice"}, {"id": "M28", "group": "M", "subject": "Métodos Quantitativos", "topic": 4, "html": "<p>Um coeficiente do objetivo muda dentro da faixa de estabilidade, preservando o mesmo ponto ótimo. O valor de Z:<\/p>", "options": ["Pode mudar mesmo sem mudar as quantidades ótimas", "É obrigado a permanecer igual", "Fica sempre zero", "Torna a solução automaticamente inviável"], "correct": 0, "explain": "O valor do objetivo depende dos coeficientes, além das quantidades.", "type": "choice"}, {"id": "M29", "group": "M", "subject": "Métodos Quantitativos", "topic": 4, "html": "<p>A soma das frações da regra dos 100% ultrapassa 1. Quando a regra é aplicável, isso significa:<\/p>", "options": ["A regra não garante estabilidade; é preciso reavaliar", "A solução necessariamente ficou inviável", "A solução necessariamente deixou de ser ótima", "Os preços-sombra dobraram"], "correct": 0, "explain": "A regra dá condição suficiente; ultrapassá-la retira a garantia, sem provar mudança.", "type": "choice"}, {"id": "M30", "group": "M", "subject": "Métodos Quantitativos", "topic": 4, "html": "<p>O recurso está além do intervalo do preço-sombra informado. Qual conduta é correta?<\/p>", "options": ["Reotimizar ou reavaliar a sensibilidade", "Extrapolar o mesmo preço indefinidamente", "Multiplicar sempre por zero", "Ignorar as demais restrições"], "correct": 0, "explain": "O preço marginal é local; mudanças de base podem alterar seu valor.", "type": "choice"}, {"id": "L11", "group": "L", "subject": "LPS", "topic": 0, "html": "<p>Uma família de produtos compartilha arquitetura, requisitos e testes e permite opções planejadas. Isso caracteriza:<\/p>", "options": ["Linha de Produtos de Software", "Cópia casual sem gestão de diferenças", "Produto único sem qualquer reutilização", "Migração obrigatória para microsserviços"], "correct": 0, "explain": "LPS combina ativos comuns e variabilidade gerida em um domínio.", "type": "choice"}, {"id": "L12", "group": "L", "subject": "LPS", "topic": 0, "html": "<p>Qual ativo pode ser reutilizado numa LPS além do código?<\/p>", "options": ["Requisitos, arquitetura e casos de teste", "Apenas o nome comercial", "Somente o contrato do fornecedor", "Exclusivamente imagens da interface"], "correct": 0, "explain": "Reuso sistemático abrange diversos artefatos do desenvolvimento.", "type": "choice"}, {"id": "L13", "group": "L", "subject": "LPS", "topic": 0, "html": "<p>Uma arquitetura que serve à família inteira é chamada:<\/p>", "options": ["Arquitetura de referência", "Instância exclusiva de um cliente", "Requisito delta", "Teste unitário descartável"], "correct": 0, "explain": "A arquitetura de referência orienta as especializações das aplicações.", "type": "choice"}, {"id": "L14", "group": "L", "subject": "LPS", "topic": 0, "html": "<p>Qual associação está correta?<\/p>", "options": ["Domínio desenvolve para reuso; aplicação desenvolve com reuso", "Domínio só vende; aplicação cria toda a plataforma do zero", "Domínio só testa; aplicação define o mercado inteiro", "Ambas dispensam gestão de variabilidade"], "correct": 0, "explain": "A distinção central é criar ativos reutilizáveis e derivar produtos com eles.", "type": "choice"}, {"id": "L15", "group": "L", "subject": "LPS", "topic": 1, "html": "<p>Uma variante A excludes B. O produto pode incluir ambas?<\/p>", "options": ["Não; a restrição impede coexistência", "Sim; excludes significa que B é obrigatória", "Sim; restrições só valem nos testes", "Não; toda variante opcional é proibida"], "correct": 0, "explain": "Excludes representa incompatibilidade entre escolhas.", "type": "choice"}, {"id": "L16", "group": "L", "subject": "LPS", "topic": 1, "html": "<p>Um grupo permite escolher entre 1 e 2 de 3 variantes. Qual seleção é válida?<\/p>", "options": ["Duas variantes", "Nenhuma variante", "As três variantes", "Quatro variantes"], "correct": 0, "explain": "A cardinalidade [1,2] limita a quantidade mínima e máxima escolhida.", "type": "choice"}, {"id": "L17", "group": "L", "subject": "LPS", "topic": 1, "html": "<p>A escolha de banco é definida apenas na configuração de implantação. Isso descreve:<\/p>", "options": ["Tempo de ligação da variabilidade", "Duplicação do domínio", "Eliminação do ponto de variação", "Defeito de compilação inevitável"], "correct": 0, "explain": "Tempo de ligação é quando se resolve a escolha entre variantes.", "type": "choice"}, {"id": "L18", "group": "L", "subject": "LPS", "topic": 1, "html": "<p>Qual é exemplo de variabilidade interna?<\/p>", "options": ["Escolher a biblioteca de persistência usada pela implementação", "Cliente escolher o plano visível na tela", "Usuário selecionar o idioma exibido", "Cliente contratar o módulo de faturamento"], "correct": 0, "explain": "Variabilidade interna diz respeito a decisões técnicas; a externa é percebida pelo cliente.", "type": "choice"}, {"id": "L19", "group": "L", "subject": "LPS", "topic": 2, "html": "<p>Uma empresa constrói ativos-base antes de derivar a família prevista. A abordagem é:<\/p>", "options": ["Proativa", "Extrativa", "Aplicação pura", "Força bruta"], "correct": 0, "explain": "Proativa antecipa os ativos; extrativa parte de produtos existentes.", "type": "choice"}, {"id": "L20", "group": "L", "subject": "LPS", "topic": 2, "html": "<p>A base da LPS é ampliada conforme chegam novos requisitos e produtos. Isso é:<\/p>", "options": ["Abordagem reativa", "Abordagem extrativa obrigatória", "Teste de força bruta", "Ausência de engenharia de domínio"], "correct": 0, "explain": "Reativa evolui a plataforma incrementalmente conforme as demandas.", "type": "choice"}, {"id": "L21", "group": "L", "subject": "LPS", "topic": 2, "html": "<p>Qual risco deve ser considerado ao adotar LPS?<\/p>", "options": ["Investimento inicial e gestão de configurações", "Proibição de reutilizar testes", "Impossibilidade de produzir mais de um produto", "Ausência de qualquer custo de manutenção"], "correct": 0, "explain": "Benefícios de reuso exigem investimento, escopo adequado e gestão.", "type": "choice"}, {"id": "L22", "group": "L", "subject": "LPS", "topic": 2, "html": "<p>Três sistemas existentes serão analisados para formar uma plataforma comum. Qual estratégia descreve a iniciativa?<\/p>", "options": ["Extrativa", "Proativa sem produtos prévios", "Exclusão de variantes", "Teste de aplicação pura"], "correct": 0, "explain": "A abordagem extrativa identifica comuns e variáveis em produtos já existentes.", "type": "choice"}, {"id": "L23", "group": "L", "subject": "LPS", "topic": 3, "html": "<p>Um cliente pede recurso ausente nos ativos de domínio. Primeiro, é adequado:<\/p>", "options": ["Avaliar o delta e seu impacto em custo, arquitetura e testes", "Adicionar código sem analisar efeitos", "Ignorar o requisito sem negociação", "Eliminar a arquitetura de referência"], "correct": 0, "explain": "Deltas precisam de análise e podem exigir extensão dos ativos ou adaptação específica.", "type": "choice"}, {"id": "L24", "group": "L", "subject": "LPS", "topic": 3, "html": "<p>Ao derivar uma aplicação, qual relação entre suas arquiteturas é esperada?<\/p>", "options": ["A arquitetura da aplicação especializa a de referência", "As arquiteturas jamais podem compartilhar elementos", "A arquitetura de referência contém apenas dados de um cliente", "A aplicação precisa eliminar todos os componentes comuns"], "correct": 0, "explain": "A derivação seleciona e adapta elementos da plataforma para o produto concreto.", "type": "choice"}, {"id": "L25", "group": "L", "subject": "LPS", "topic": 3, "html": "<p>Uma alteração de variante exige descobrir requisitos e testes afetados. Qual vínculo é necessário?<\/p>", "options": ["Rastreabilidade entre artefatos", "Somente quantidade de commits", "Apenas data de criação do produto", "Duplicação de todo o repositório"], "correct": 0, "explain": "Rastreabilidade permite analisar impactos ao conectar variabilidade e artefatos.", "type": "choice"}, {"id": "L26", "group": "L", "subject": "LPS", "topic": 3, "html": "<p>Reutilizar um componente numa aplicação significa que:<\/p>", "options": ["Ele ainda precisa ser integrado e validado no contexto", "Seu comportamento nunca depende do contexto", "Todos os testes da aplicação são dispensáveis", "Ele deve ser necessariamente reescrito"], "correct": 0, "explain": "Reuso economiza esforço, mas não elimina verificação da configuração e integração.", "type": "choice"}, {"id": "L27", "group": "L", "subject": "LPS", "topic": 4, "html": "<p>Testar todas as combinações possíveis de uma LPS é a estratégia:<\/p>", "options": ["Força bruta", "Aplicativo de amostra", "Reativa", "Extrativa"], "correct": 0, "explain": "Força bruta pode se tornar impraticável pela explosão combinatória.", "type": "choice"}, {"id": "L28", "group": "L", "subject": "LPS", "topic": 4, "html": "<p>Qual vantagem dos aplicativos de amostra no teste de domínio?<\/p>", "options": ["Antecipar validação com configurações representativas", "Garantir que nenhuma aplicação precise de teste", "Cobrir automaticamente todas as combinações possíveis", "Eliminar a necessidade de variantes"], "correct": 0, "explain": "Amostras ajudam a validar cedo, mas exigem complementação nos produtos reais.", "type": "choice"}, {"id": "L29", "group": "L", "subject": "LPS", "topic": 4, "html": "<p>Concentrar testes somente nos produtos finais, sem testar ativos no domínio, caracteriza:<\/p>", "options": ["Aplicação pura", "Desenvolvimento proativo", "Teste de força bruta", "Modelo ortogonal"], "correct": 0, "explain": "Aplicação pura perde validação antecipada e pode repetir esforço entre produtos.", "type": "choice"}, {"id": "L30", "group": "L", "subject": "LPS", "topic": 4, "html": "<p>Cinco pontos independentes, exatamente uma escolha entre duas opções em cada, geram:<\/p>", "options": ["32 configurações", "10 configurações", "25 configurações", "64 configurações"], "correct": 0, "explain": "O produto das escolhas é 2⁵=32, sem outras restrições.", "type": "choice"}, {"id": "A11", "group": "A", "subject": "Android", "topic": 0, "html": "<p>Em React Native, justifyContent atua em qual eixo?<\/p>", "options": ["No eixo principal definido por flexDirection", "Sempre no eixo horizontal, independentemente do layout", "Sempre no eixo vertical, independentemente do layout", "No eixo de persistência de dados"], "correct": 0, "explain": "Os eixos dependem de flexDirection; alignItems atua no transversal.", "type": "choice"}, {"id": "A12", "group": "A", "subject": "Android", "topic": 0, "html": "<p>Qual componente organiza uma lista em grupos com cabeçalhos de seção?<\/p>", "options": ["SectionList", "TextInput", "Image", "Button"], "correct": 0, "explain": "SectionList é apropriado para listas seccionadas; FlatList organiza uma lista virtualizada simples.", "type": "choice"}, {"id": "A13", "group": "A", "subject": "Android", "topic": 0, "html": "<p>Qual propriedade liga a digitação de um TextInput à atualização do nome?<\/p>", "options": ["onChangeText", "onPressText obrigatório", "executeSql", "keyExtractor"], "correct": 0, "explain": "onChangeText recebe o texto e pode chamar o atualizador do estado.", "type": "choice"}, {"id": "A14", "group": "A", "subject": "Android", "topic": 0, "html": "<p>Qual modelo de navegação representa um menu lateral?<\/p>", "options": ["Drawer", "Stack", "Reducer", "DAO"], "correct": 0, "explain": "Drawer apresenta menu lateral; stack é pilha e tabs são abas.", "type": "choice"}, {"id": "A15", "group": "A", "subject": "Android", "topic": 1, "html": "<p>Ao recuperar um texto JSON do AsyncStorage, usa-se para reconstruir o objeto:<\/p>", "options": ["JSON.parse", "JSON.stringify", "Base64.encode", "executeSql"], "correct": 0, "explain": "parse desserializa JSON; stringify faz o caminho do objeto para texto.", "type": "choice"}, {"id": "A16", "group": "A", "subject": "Android", "topic": 1, "html": "<p>Qual sequência corresponde ao SQLite apresentado no material?<\/p>", "options": ["Abrir banco, iniciar transação, executar SQL", "Criar action, dispatcher, renderizar", "Codificar Base64, consultar WSDL, fechar view", "Definir props, emitir tópico, criar Servlet"], "correct": 0, "explain": "O fluxo usa conexão e transação para executar operações SQL.", "type": "choice"}, {"id": "A17", "group": "A", "subject": "Android", "topic": 1, "html": "<p>Encerrar o aplicativo faz desaparecer um objeto mantido só em state. Por quê?<\/p>", "options": ["Estado em memória não equivale a persistência", "State é sempre salvo em disco automaticamente", "Todo objeto React é banco Realm", "O aplicativo só poderia funcionar conectado"], "correct": 0, "explain": "Persistência mantém dados além do ciclo de vida do processo; state é memória de execução.", "type": "choice"}, {"id": "A18", "group": "A", "subject": "Android", "topic": 1, "html": "<p>Na solução React Native com MongoDB remoto do material, o cliente normalmente acessa:<\/p>", "options": ["Um servidor/API intermediário", "Diretamente os arquivos físicos do banco no dispositivo", "Apenas um StyleSheet", "Uma função de navegação drawer"], "correct": 0, "explain": "O backend expõe operações de persistência ao aplicativo por uma API.", "type": "choice"}, {"id": "A19", "group": "A", "subject": "Android", "topic": 2, "html": "<p>No Axios, o corpo da resposta costuma ser acessado em:<\/p>", "options": ["resposta.data", "resposta.executeSql", "resposta.props", "resposta.reducer"], "correct": 0, "explain": "Axios normalmente converte o corpo e o expõe em data; Fetch usa Response e json().", "type": "choice"}, {"id": "A20", "group": "A", "subject": "Android", "topic": 2, "html": "<p>Para enviar um objeto como JSON com Fetch, qual combinação é apropriada?<\/p>", "options": ["Content-Type application/json e body com JSON.stringify", "Content-Type image/png e body com função React", "Só mudar o nome da URL para json", "Usar JSON.parse no objeto antes de enviá-lo"], "correct": 0, "explain": "O cabeçalho descreve o formato; stringify converte o objeto em texto JSON.", "type": "choice"}, {"id": "A21", "group": "A", "subject": "Android", "topic": 2, "html": "<p>Fetch recebe uma resposta HTTP 404. Qual conduta é adequada?<\/p>", "options": ["Verificar r.ok/status e tratar o erro HTTP", "Assumir que toda Promise foi rejeitada automaticamente", "Tratar 404 como sucesso de criação", "Apagar o banco local imediatamente"], "correct": 0, "explain": "Erros HTTP e falhas de rede são situações distintas na API Fetch.", "type": "choice"}, {"id": "A22", "group": "A", "subject": "Android", "topic": 2, "html": "<p>Dois usuários editaram o mesmo item offline. Ao sincronizar, é necessário:<\/p>", "options": ["Uma política de resolução de conflitos", "Apenas trocar View por Text", "Apenas verificar se o Wi-Fi está ligado", "Eliminar todos os dados locais sem comparar"], "correct": 0, "explain": "Conectividade não decide qual versão prevalece ou como mesclar mudanças.", "type": "choice"}, {"id": "A23", "group": "A", "subject": "Android", "topic": 3, "html": "<p>No MVC, um DAO é responsável principalmente por:<\/p>", "options": ["Encapsular acesso aos dados", "Desenhar botões e cores", "Distribuir rotas de navegação", "Assinar o pacote para a loja"], "correct": 0, "explain": "DAO separa operações de persistência do restante da aplicação.", "type": "choice"}, {"id": "A24", "group": "A", "subject": "Android", "topic": 3, "html": "<p>Qual ação de um reducer Redux é adequada?<\/p>", "options": ["Calcular e devolver novo estado a partir de estado e action", "Modificar diretamente o objeto recebido e ocultar a mudança", "Atualizar o banco dentro de cada renderização", "Substituir a View por um dispatcher"], "correct": 0, "explain": "Reducers calculam transições sem mutação direta do estado recebido.", "type": "choice"}, {"id": "A25", "group": "A", "subject": "Android", "topic": 3, "html": "<p>Qual elemento é característico do Flux descrito no material?<\/p>", "options": ["Dispatcher encaminhando ações às stores", "Repository JPA executado no dispositivo", "WSDL definindo a interface visual", "Keyspace renderizando componentes"], "correct": 0, "explain": "Flux organiza fluxo unidirecional com actions, dispatcher, stores e views.", "type": "choice"}, {"id": "A26", "group": "A", "subject": "Android", "topic": 3, "html": "<p>Uma action no Redux descreve principalmente:<\/p>", "options": ["Um evento que orienta a transição de estado", "A posição fixa de um botão na tela", "Um algoritmo de criptografia", "Um arquivo de banco SQLite"], "correct": 0, "explain": "Action informa o evento; reducer determina a mudança de estado.", "type": "choice"}, {"id": "A27", "group": "A", "subject": "Android", "topic": 4, "html": "<p>Qual é uma propriedade de uma função hash?<\/p>", "options": ["Produzir resumo sem operação normal de reversão", "Usar sempre a mesma chave para cifrar e decifrar", "Ser sinônimo de Base64", "Garantir reconstrução exata do original por decode"], "correct": 0, "explain": "Hash não é criptografia reversível nem codificação Base64.", "type": "choice"}, {"id": "A28", "group": "A", "subject": "Android", "topic": 4, "html": "<p>Na criptografia simétrica, usa-se:<\/p>", "options": ["A mesma chave secreta para cifrar e decifrar", "Uma chave pública obrigatória para cada propriedade JSX", "Nenhuma chave", "Um hash reversível chamado parse"], "correct": 0, "explain": "AES é exemplo de criptografia simétrica; assimétrica utiliza um par de chaves.", "type": "choice"}, {"id": "A29", "group": "A", "subject": "Android", "topic": 4, "html": "<p>Em um teste Jest, expect serve para:<\/p>", "options": ["Verificar se um resultado satisfaz uma expectativa", "Publicar automaticamente o app", "Abrir conexão SQLite", "Criar token de autenticação"], "correct": 0, "explain": "Testes usam expectativas para conferir o comportamento observado.", "type": "choice"}, {"id": "A30", "group": "A", "subject": "Android", "topic": 4, "html": "<p>Antes da distribuição de um aplicativo, qual etapa faz parte do processo?<\/p>", "options": ["Gerar build de distribuição, assinar e testar", "Apenas mudar o título de uma View", "Converter todo o código para Base64", "Excluir os testes para acelerar"], "correct": 0, "explain": "O fluxo de publicação envolve build, assinatura, identificação e validação.", "type": "choice"}, {"id": "B11", "group": "B", "subject": "Back-end", "topic": 0, "html": "<p>Qual código HTTP indica recurso criado?<\/p>", "options": ["201", "404", "500", "401"], "correct": 0, "explain": "201 indica criação; 404 é ausência, 500 erro interno e 401 falta de autenticação válida.", "type": "choice"}, {"id": "B12", "group": "B", "subject": "Back-end", "topic": 0, "html": "<p>Qual método HTTP é associado a substituir o estado do recurso identificado e tem semântica idempotente?<\/p>", "options": ["PUT", "POST sem garantia adicional", "CONNECT", "TRACE"], "correct": 0, "explain": "PUT é idempotente; repetir o mesmo estado tem o mesmo efeito pretendido.", "type": "choice"}, {"id": "B13", "group": "B", "subject": "Back-end", "topic": 0, "html": "<p>AJAX pode transmitir JSON?<\/p>", "options": ["Sim; não está limitado a XML", "Não; o nome proíbe qualquer outro formato", "Somente se a aplicação não tiver servidor", "Somente por meio de JDBC"], "correct": 0, "explain": "AJAX descreve comunicação assíncrona para atualização da interface e aceita vários formatos.", "type": "choice"}, {"id": "B14", "group": "B", "subject": "Back-end", "topic": 0, "html": "<p>Qual condição é de XML bem formado?<\/p>", "options": ["Raiz única e tags corretamente aninhadas", "Todas as tags definidas obrigatoriamente pelo HTML", "Chaves e colchetes em vez de tags", "Proibição de atributos"], "correct": 0, "explain": "Bem formado é diferente de validar contra DTD/XSD; fechamento e hierarquia precisam estar corretos.", "type": "choice"}, {"id": "B15", "group": "B", "subject": "Back-end", "topic": 1, "html": "<p>Qual ordem resume o ciclo de vida de um Servlet?<\/p>", "options": ["init, atendimento por service, destroy", "destroy, init, executeQuery", "render, reducer, dispatcher", "commit, rollback, parse"], "correct": 0, "explain": "O contêiner inicializa, atende requisições e encerra o Servlet.", "type": "choice"}, {"id": "B16", "group": "B", "subject": "Back-end", "topic": 1, "html": "<p>Um redirect HTTP faz o quê?<\/p>", "options": ["Orienta o cliente a fazer nova requisição", "Encaminha internamente sem resposta ao cliente", "Transforma JSP em tabela", "Abre transação no banco automaticamente"], "correct": 0, "explain": "Redirect difere de forward: o cliente realiza uma nova requisição.", "type": "choice"}, {"id": "B17", "group": "B", "subject": "Back-end", "topic": 1, "html": "<p>Qual benefício de PreparedStatement com parâmetros?<\/p>", "options": ["Separar dados do comando em vez de concatenar entradas", "Eliminar a necessidade de conexão", "Transformar SQL em interface gráfica", "Garantir resposta em tempo constante"], "correct": 0, "explain": "Parâmetros evitam construir a instrução SQL com concatenação do conteúdo do usuário.", "type": "choice"}, {"id": "B18", "group": "B", "subject": "Back-end", "topic": 1, "html": "<p>Qual distinção entre Tomcat e GlassFish é adequada ao material?<\/p>", "options": ["Tomcat é contêiner Servlet/JSP; GlassFish oferece serviços corporativos mais amplos", "Tomcat é banco de dados; GlassFish é linguagem", "Ambos são apenas bibliotecas de JSON", "GlassFish só roda no navegador"], "correct": 0, "explain": "Não trate Tomcat isolado como implementação de todos os serviços Java EE/Jakarta EE.", "type": "choice"}, {"id": "B19", "group": "B", "subject": "Back-end", "topic": 2, "html": "<p>A injeção de dependências permite:<\/p>", "options": ["Receber dependências geridas pelo contêiner", "Eliminar todos os objetos Java", "Dispensar interfaces HTTP", "Executar toda consulta no navegador"], "correct": 0, "explain": "DI entrega as dependências, reduzindo a necessidade de o objeto construí-las diretamente.", "type": "choice"}, {"id": "B20", "group": "B", "subject": "Back-end", "topic": 2, "html": "<p>Em JpaRepository&lt;Aluno, Long&gt;, Long representa:<\/p>", "options": ["O tipo do identificador da entidade", "O tempo máximo da requisição", "O nome da tabela", "O tamanho obrigatório de cada campo"], "correct": 0, "explain": "Os parâmetros genéricos indicam entidade e tipo do ID.", "type": "choice"}, {"id": "B21", "group": "B", "subject": "Back-end", "topic": 2, "html": "<p>Qual anotação captura o valor de id em uma rota /alunos/{id}?<\/p>", "options": ["@PathVariable", "@Entity", "@Document", "@Service"], "correct": 0, "explain": "PathVariable captura parte variável da URL; RequestBody lê o corpo.", "type": "choice"}, {"id": "B22", "group": "B", "subject": "Back-end", "topic": 2, "html": "<p>Qual sequência de camadas é usual numa API com Spring?<\/p>", "options": ["Controller, service, repository, banco", "Banco, View, dispatcher, CSS", "Repository, navegador, WSDL, modelo gráfico", "Controller, driver de tela, reducer, props"], "correct": 0, "explain": "O controller recebe, o serviço coordena regras e o repositório acessa persistência.", "type": "choice"}, {"id": "B23", "group": "B", "subject": "Back-end", "topic": 3, "html": "<p>No RabbitMQ, uma exchange serve principalmente para:<\/p>", "options": ["Rotear mensagens para filas conforme bindings", "Substituir o consumidor como processador de negócio", "Armazenar páginas JSP", "Executar consultas JPA"], "correct": 0, "explain": "Exchange roteia; filas mantêm entregas para os consumidores.", "type": "choice"}, {"id": "B24", "group": "B", "subject": "Back-end", "topic": 3, "html": "<p>Uma exchange direct normalmente usa:<\/p>", "options": ["Correspondência de routing key com binding key", "Sempre todas as filas, ignorando chaves", "Somente a ordem alfabética dos consumidores", "Chaves de partição Cassandra"], "correct": 0, "explain": "Direct usa correspondência; fanout distribui a todas as filas vinculadas.", "type": "choice"}, {"id": "B25", "group": "B", "subject": "Back-end", "topic": 3, "html": "<p>Um consumidor recebe novamente uma mensagem após falha. Que característica ajuda a evitar efeitos duplicados?<\/p>", "options": ["Processamento idempotente", "Adicionar um novo botão", "Remover todos os acknowledgments", "Trocar JSON por XML sem outra mudança"], "correct": 0, "explain": "Idempotência permite repetir a operação sem duplicar seu efeito pretendido.", "type": "choice"}, {"id": "B26", "group": "B", "subject": "Back-end", "topic": 3, "html": "<p>Em JMS, Queue e Topic representam respectivamente:<\/p>", "options": ["Fila ponto a ponto e destino publish/subscribe", "Banco relacional e banco documental", "Servlet e página JSP", "Request e Response HTTP"], "correct": 0, "explain": "São os dois domínios clássicos de mensageria; não são tecnologias de persistência.", "type": "choice"}, {"id": "B27", "group": "B", "subject": "Back-end", "topic": 4, "html": "<p>No SOAP, qual documento descreve o contrato do serviço?<\/p>", "options": ["WSDL", "JSX", "BSON", "CQL"], "correct": 0, "explain": "WSDL descreve a interface do serviço; SOAP usa mensagens XML.", "type": "choice"}, {"id": "B28", "group": "B", "subject": "Back-end", "topic": 4, "html": "<p>Um serviço devolve exatamente os campos pedidos pelo cliente por meio de um schema e resolvers. A tecnologia é:<\/p>", "options": ["GraphQL", "JDBC", "JMS", "HSTORE"], "correct": 0, "explain": "GraphQL permite consultas com seleção de campos e resolução por schema.", "type": "choice"}, {"id": "B29", "group": "B", "subject": "Back-end", "topic": 4, "html": "<p>Qual anotação é característica de JAX-RS para definir caminho de recurso?<\/p>", "options": ["@Path", "@Entity", "@Id", "@WebMethod"], "correct": 0, "explain": "JAX-RS está associado a REST; WebMethod aparece no contexto de SOAP/JAX-WS.", "type": "choice"}, {"id": "B30", "group": "B", "subject": "Back-end", "topic": 4, "html": "<p>Uma resposta REST precisa ser obrigatoriamente JSON?<\/p>", "options": ["Não; pode utilizar outras representações, como XML", "Sim; REST é o nome de um formato JSON", "Sim; XML só existe em bancos", "Não; REST proíbe qualquer corpo de resposta"], "correct": 0, "explain": "REST é estilo arquitetural e não impõe um único formato de representação.", "type": "choice"}];